<?php $where='';$args=[];if(!is_admin()){$where='AND o.user_id=?';$args[] = current_user()['id'];}$filter=(string)($_GET['status']??'');if(in_array($filter,['Diproses','Selesai','Dibatalkan'],true)){$where.=' AND o.status=?';$args[]=$filter;}$rows=orders($where,$args,100);?>
<div class="page-heading"><div><p class="eyebrow">TRANSAKSI</p><h1>Daftar pesanan</h1><p class="subheading">Pantau proses pesanan dan buka kembali nota.</p></div><a class="button primary" href="index.php?page=new-order">＋ Pesanan baru</a></div><section class="panel"><div class="filter-row"><form method="get"><input type="hidden" name="page" value="orders"><label class="sr-only" for="status-filter">Filter status</label><select id="status-filter" name="status" onchange="this.form.submit()"><option value="">Semua status</option><?php foreach(['Diproses','Selesai','Dibatalkan'] as $s):?><option <?= $filter===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach;?></select></form><span class="result-count"><?= count($rows) ?> pesanan ditampilkan</span></div><div class="table-scroll"><table><thead><tr><th>Invoice / waktu</th><th>Jenis</th><th>Pemesan</th><?php if(is_admin()):?><th>Kasir</th><?php endif;?><th>Pembayaran</th><th>Total</th><th>Status / aksi</th></tr></thead><tbody><?php foreach($rows as $o):?><tr><td><a class="invoice-link" href="index.php?page=receipt&id=<?= (int)$o['id'] ?>"><?= e($o['invoice_number']) ?></a><small class="table-sub"><?= date('d M, H:i',strtotime($o['created_at'])) ?></small></td><td><?= e($o['order_type']) ?><?= $o['table_number']?' · '.$o['table_number']:'' ?></td><td><?= e($o['customer_name']?:'—') ?></td><?php if(is_admin()):?><td><?= e($o['cashier']) ?></td><?php endif;?><td><?= e($o['payment_method']) ?></td><td class="money-cell"><?= rupiah($o['grand_total']) ?></td><td><span class="status <?= $o['status']==='Selesai'?'done':($o['status']==='Dibatalkan'?'cancelled':'pending') ?>"><?= e($o['status']) ?></span><?php if($o['status']==='Diproses'):?><form class="inline-actions" method="post"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$o['id'] ?>"><button name="status" value="Selesai" class="mini-action">Selesaikan</button><button name="status" value="Dibatalkan" class="mini-action danger-text" onclick="return confirm('Batalkan pesanan ini? Stok menu akan dikembalikan.')">Batalkan</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><div class="empty-state"><span>▤</span><strong>Belum ada pesanan</strong><p>Pesanan baru akan muncul di daftar ini.</p></div><?php endif;?></div></section>
